/* Idea map. Citations: [[key|locator]] parenthetical, [[n:key|locator]] narrative, several joined with ';'
   q = [text, origin]: y your running list (10 Oct) · p your presentation · f feedback you received · m raised by this map */
window.CLUSTERS=[
 {id:'frame',label:'Thesis frame',side:'R'},
 {id:'met',label:'Candidate metaphors',side:'R'},
 {id:'cmt',label:'Metaphor and embodiment',side:'R'},
 {id:'prac',label:'Your practice',side:'R'},
 {id:'ont',label:'Ontology of sound',side:'L'},
 {id:'lis',label:'Listening and knowledge',side:'L'},
 {id:'spa',label:'Space, sphere, atmosphere',side:'L'},
 {id:'craft',label:'Film sound craft',side:'L'}
];
window.CENTER={id:'thesis',label:'Conceptual metaphor as sound design method',
 def:'A practice-led master’s thesis asking what a deliberately applied conceptual metaphor affords and constrains in post-production film sound.',
 body:['The project began with the acoustic palimpsest, an account of worldizing and re-amplification as layered inscription [[enoch2026b|Introduction]]. It widened into a pool of five candidate metaphors and is now framed through Conceptual Metaphor Theory, with a short speculative horror film as the experiment [[enoch2026a]].',
 'The right-hand side of the map holds the thesis itself: its frame, the metaphors, the theory of metaphor and your own work. The left-hand side holds what the reading supplies: what sound is, how listening knows, how sound makes space, and how mixers already think.',
 'Select any item to read its definition, the argument with citations, an illustration where one helps, linked ideas and open questions. Switch the map to Sources to browse every reference.'],
 rel:['question','operable','palimpsest','cmt','flux','density'],
 q:[['If you could fully answer only one cluster of questions in the thesis, which would it be?','y']]};
window.NODES=[
/* ---------------- Thesis frame ---------------- */
{id:'question',c:'frame',label:'Research question',
 def:'What are the affordances and constraints of applying a conceptual metaphor in post-production film sound design?',
 body:['The research object is the process by which deliberately applied metaphors become, or fail to become, sound design decisions in your own practice [[enoch2026a]]. Failure is part of the object, so a metaphor that produces nothing is still a result.',
 'Earlier wordings are worth keeping in view because they show what has been set aside. The question was once how to initiate the audio metaphor in a filmic context, and before that what is pleasurable about doing so. The word “constraints” has a ready partner in A. Cox, for whom bodily imagery both motivates and constrains how we conceptualise music [[coxa2011|para. 61]].'],
 rel:['operable','sonicmetaphor','cmt','limit','mimetic'],
 q:[['How do I initiate the audio metaphor in a filmic context?','y'],['Who initiates it?','y'],['Does the practitioner always create a practical aesthetic?','y']]},
{id:'operable',c:'frame',label:'Operable or illustrative',fig:'operable',
 def:'An operable metaphor generates decisions. An illustrative metaphor depicts its source in sound.',
 body:['This is the sub-question: when is a conceptual metaphor operable (generative, decision-oriented) and when is it illustrative (depictive, sound-oriented) [[enoch2026a]]? In the vocabulary of metaphor theory, an operable metaphor is one whose source domain yields entailments that carry over into the work [[kovecses2017]].',
 'The library holds both kinds. Collins teaches metaphor as a sound that stands in for something else [[collins2020|p. 202]], which is the illustrative sense. Murch’s spectrum of sound colours is operable: it tells him which layer to remove when a mix clogs [[murch2005|pp. 21–22]].'],
 rel:['mapping','spectrum','metsound','tagging','sonicmetaphor','limit'],
 q:[['If a metaphor is a method, what makes one operable?','y'],['Can a decision be wrong relative to the metaphor?','y'],['When is the metaphor the workflow?','y']]},
{id:'sonicmetaphor',c:'frame',label:'Sonic metaphor (proposed term)',
 def:'Your proposed name for an operable conceptual metaphor in sound design: a figure of speech that can be worked within as a method.',
 body:['The proposal is on the presentation slide [[enoch2026a]]. After presenting, you found that audiences could not follow “sonic metaphor of sound design” and began to suspect a misnomer. Your reframing: listening is a form of understanding, so an ontological perspective creates a new way of listening. The metaphor is not a sound. It is a revelation of sound framed by a metaphor.',
 'The term is already in use with the opposite meaning. Collins sets an exercise called Sonic Metaphors about sounds that symbolise something else [[collins2020|p. 202]], and Madupu and Coëgnarts use the phrase for metaphors an audience reads [[madupu2025]]. Your own earliest use is in the <i>Em Chamas</i> paper, where the machine becomes a sonic metaphor [[sarantopoulos2026|The Boy as a Machine]].'],
 rel:['operable','revelation','emchamas','embodiedfilm','metsound'],
 q:[['Is it a feeling, a filter, a flanger?','y'],['The term collides with Collins and with Madupu and Coëgnarts. Is a redefinition defensible, or does the idea need a new name?','m']]},
{id:'method',c:'frame',label:'Practice-led research',
 def:'New understanding of a method emerges from making a film, and a text accompanies and contextualises the findings.',
 body:['Seven methods are listed [[enoch2026a]]: critical viewing and reading for the literature review; CMT mapping of source onto target; a tagging system; comparative sound design; a reflective production diary (autoethnography, theory-fiction); a studio log; and sound diagramming of affordances and constraints.',
 'Two library sources model the stance. Murch presents his rules as one person’s working methods, useful whether or not they are finally true [[murch2005|pp. 37–38]]. Ingold argues that knowledge is made by going along a path and is not assembled afterwards from fixed points [[ingold2010|pp. S121–S122]].'],
 rel:['comparative','tagging','wayfaring','text','thesisfilm'],
 q:[['Limit the findings to my practice and do not generalise: what would count as going too far?','p']]},
{id:'comparative',c:'frame',label:'Comparative sound design',fig:'design',
 def:'Designing one scene under several metaphors, and comparing the results with each other and with your standard workflow.',
 body:['It sits in phase 3 of the research design, after picture lock, with the rule that the metaphor is not applied to the visuals [[enoch2026a]]. The standard workflow is the baseline that shows what the metaphor added.',
 'Murch supplies a caution for any comparison of mixes. On <i>THX 1138</i> a density that felt right against a small, dim image became unbearable against the full colour print [[murch2005|p. 38]]. Versions should be judged under the same picture, level and room.'],
 rel:['method','tagging','density','thesisfilm','operable'],
 q:[['How do you stop the third version of a scene from learning from the first two?','m'],['Which two or three of the five metaphors go forward to the comparison, and on what grounds?','m']]},
{id:'tagging',c:'frame',label:'Tagging and the studio log',
 def:'A session-by-session record in text, photo and video in which each decision is traced back to a metaphor.',
 body:['The log is the evidence for phases 3 and 4. It is organised after the fact and compared with the mapping made in pre-production [[enoch2026a]]. Sound diagrams then draw the affordances and constraints that the log reveals.',
 'Ingold offers a useful friction. He contrasts knowledge that classifies and arranges with knowledge that is storied, where each impression is placed among the events that led to it [[ingold2010|p. S135]]. A tag classifies. A log entry can also tell the story of a decision.'],
 rel:['wayfaring','comparative','operable','method'],
 q:[['What are the tag categories? For example: traced to an entailment, untraced, illustrative, metaphor failed.','m'],['Tagging classifies and Ingold’s wayfarer narrates. Can the studio log do both?','m']]},
{id:'horror',c:'frame',label:'Speculative horror',
 def:'The genre frame of the thesis film: horror as access to the uncaring, raw materials of existence.',
 body:['The slide names Thacker’s world-without-us and gives the reason for the genre in three words: ambiguity breeds possibility [[enoch2026a;thacker2011]]. For you abstraction comes first, and horror lives in the ambiguity that results.',
 'The library converges on one image of this dread. Murch and Sloterdijk both quote Pascal on the silence of infinite space: Murch to explain why silence threatens [[murch2005|p. 25]], Sloterdijk to describe modern life outside any protective shell [[sloterdijk2011|pp. 22–23]]. Jarvis reports Ihde taming a whale’s cry by giving it a natural context [[jarvis2024|sec. 2.2]], which is the opposite movement: sound made safe.'],
 rel:['silence','sphere','abject','flux','thesisfilm','bubble'],
 q:[['What does the abstract horror form let you do sonically that another form would not?','f'],['How are you defining horror, and how abstraction?','f']]},
{id:'text',c:'frame',label:'Text, theory-fiction, documentation',
 def:'The written and archival half of the thesis: framework, methods, findings and poetic interludes, plus the studio log, diagrams and comparable sound examples.',
 body:['Theory-fiction is planned as a mode of writing, with the question of whether form can carry meaning and make theory more accessible [[enoch2026a]]. Documentation may be exhibited on the Research Catalogue.',
 'There are precedents close to hand. Bañuelos Loreto opens each chapter with a slice of literature chosen as part of a rhizomatic process [[banuelos2018|p. 128]], and your palimpsest essay sets its title as a broken poem [[enoch2026b|Abstract]].'],
 rel:['method','rhizome','thesisfilm'],
 q:[['Can the form carry meaning, with theory-fiction making theory more accessible?','p'],['What consent is needed for hybrid-documentary subjects and for interviews at test screenings?','p'],['Subtitles for the film? An audio version of the text?','p']]},
/* ---------------- Candidate metaphors ---------------- */
{id:'palimpsest',c:'met',t:'met',label:'The Palimpsest',fig:'palimpsest',
 def:'Sound treated as layered inscription with imperfect erasure: what was removed still shows through the present mix.',
 body:['Your essay builds it from Dillon’s palimpsest, whose present always holds past and future moments entangled [[dillon2007|pp. 4–37]], and from Bonnet’s traces, his “absent presences” [[bonnet2016|p. 25]]. You argue for an atmospheric palimpsest in place of a textual one [[enoch2026b|Abstract]]. Chion offers a film-historical cousin: every sound film carries a silent film within it [[chion2009|p. 171]].',
 'Two objections are already in your reading. Daughtry warns that the figure treats the world as a text and files hearing under writing [[daughtry2017|p. 78]]. Ingold rejects the ground-as-palimpsest outright: a walker does not add a layer to a surface, he weaves another strand of movement into it [[ingold2010|p. S128]].',
 'Working one-line version from your October sessions: because scraped writing never fully disappears, removed sounds leave audible residue. Muted regions leak, tails remain and old ambiences show through new layers.'],
 rel:['reamp','worldizing','infrathin','thick','aurality','wayfaring','limit','installation'],
 q:[['Why the palimpsest as the second ontology? What does layering with traces explain that spheres do not?','y'],['Ingold says a path is woven into the ground and is not a layer on it. Does the acoustic palimpsest survive that, or become a weave?','m'],['Campbell (2011) is in your bibliography on palimpsest and porosity in film sound. What does it add?','m']]},
{id:'echo',c:'met',t:'met',label:'The Echo',fig:'echo',
 def:'A sound never returns as itself: it comes back late, carrying the shape of everything it crossed.',
 body:['LaBelle gives the figure its logic. The echo stages the passing of sound, returns the event reshaped, and makes duration into something spatial: “the echo turns sound into sculpture” [[labelle2019|p. 4]]. It disorients, breaks the line from past to future, and can bring forward what was repressed [[labelle2019|pp. 4–5]].',
 'You have pushed it toward subjectivity: the listening subject as a structure of referral, constituted like an echo [[schmidt2021;nancy2007]]. Jarvis reaches the same Nancy by another road [[jarvis2024|sec. 2.5]]. Your essay adds the historical stake, the echolessness of modern recorded sound [[erlmann2010]].',
 'The Echo needs separation: a distance, a delay and something other that answers. That is what keeps it apart from the Fold.'],
 rel:['territory','auralarch','worldizing','fold','listening','palimpsest'],
 q:[['Your mentor said there is a lot of good writing on the echo and named none. Which echo literature anchors it?','f'],['Every reverb is an echo of a kind. What makes its use operable and not illustrative?','m']]},
{id:'infection',c:'met',t:'met',label:'The Infection',fig:'infection',
 def:'A sonic trait introduced in one element spreads by contact until the whole mix carries it. Also listed as Contagion and Transmission.',
 body:['It comes from your own work: <i>Anything That Moves</i> was conceived as the infection of a mythic-americana soundscape by a lawn sprinkler and an ice cream truck. It is the one candidate that began as a design idea and not as a reading.',
 'Sloterdijk supplies its opposite number. If people now orient themselves by “the general theory of immune systems” [[sloterdijk2011|p. 25]], then the sphere is the immune structure and infection is what gets through it. LaBelle’s vibration is a model of spread by contact, passing between bodies and surfaces below the threshold of hearing [[labelle2019|pp. 95–97]].',
 'An earlier framing of the whole thesis used the same word for the path from designer to audience: ontological inhabitation, then creative contagion, then spectator validation.'],
 rel:['atm','sphere','bubble','territory','mimetic','abject'],
 q:[['In <i>Anything That Moves</i>, which choices are only explainable through the infection metaphor, and which would have happened anyway?','y'],['Is infection a metaphor for the mix, or for how a metaphor passes from designer to audience?','m']]},
{id:'fold',c:'met',t:'met',label:'The Fold (and the Wave)',fig:'fold',
 def:'Sound is one continuous surface that folds inward to form each listener, character or space. Meaning comes from unfolding what the fold already holds.',
 body:['You asked for this one to be Deleuzian or Ingoldian: the Baroque fold and its spirals [[deleuze1993]], and Ingold’s being as an enfoldment of life’s generative potential [[ingold2000|p. 19]]. Neither text is in the library yet.',
 'On the slide it is paired with the Wave [[enoch2026a]]. They give different instructions. A wave interferes, reinforcing or cancelling. A fold implicates, holding the outside within. LaBelle’s prose uses folding for both echo and vibration [[labelle2019|pp. 4, 95]], a sign of how easily the figure blurs into its neighbours.',
 'What separates it from the Bubble: there is no membrane. The inside is the outside, folded.'],
 rel:['bubble','echo','matimag','intensity','shelf','medium'],
 q:[['Wave or Fold? The slide pairs them and they prescribe different moves.','m'],['What does the Fold say once Deleuze’s first chapter has actually been read?','m']]},
{id:'bubble',c:'met',t:'met',label:'The Bubble',fig:'bubble',
 def:'A sonic world as a thin, shared membrane that separates inside from outside, with the outside pressing on it until it bursts.',
 body:['Bubbles are Sloterdijk’s smallest spheres, the intimate two-poled interiors from which larger worlds are built [[sloterdijk2011|pp. 62–63]]. His book opens with a child whose attention travels out with the soap bubble he has blown [[sloterdijk2011|p. 17]]. Sound is central to the account: voices make acoustic coverings that one joins by being inside them [[sloterdijk2011|p. 297]].',
 'You kept this name over “Sphere.” It is the one candidate that is an ontological metaphor in Lakoff and Johnson’s strict sense, because it is a container [[lakoff1980]]. Abels is the caution: the sonosphere sensitises analysis and cannot stand as an explanation [[abels2016|p. 153]].'],
 rel:['sphere','sonosphere','kinds','infection','ambience','fold','horror'],
 q:[['What does Sloterdijk’s immune-system sphere do to your reading of a soundscape that another framework would not?','y'],['A bubble has two poles. Who shares the inside of a film’s bubble: two characters, or a character and the audience?','m']]},
{id:'shelf',c:'met',t:'met',label:'On the shelf: Stain, Atmosphere',
 def:'Figures collected earlier and not in the current pool of five.',
 body:['The September lexicon had five figures: Bubble, Wave, Echo, Stain and Atmosphere. The Stain came from Lacan, as sound that exceeds the frame and marks it from outside. A mentor pointed to live theatre as the place where the real punctures through. The Atmosphere came from Ingold’s weather-world [[ingold2010|p. S131]] and from Connor’s gaseous sound in your essay [[connor2011]].',
 'A cohort pedagogy with one designer per metaphor, and a film designed five times and spliced, are parked as future extensions [[enoch2026a]]. You also see Bloom’s six revisionary ratios as close kin to the pool [[bloom1973]].'],
 rel:['medium','abject','fold','matimag','ambience'],
 q:[['How many sonic ontologies can a film support?','y'],['What made the Stain and the Atmosphere drop out, and is that reason a finding about operability?','m']]},
/* ---------------- Metaphor and embodiment ---------------- */
{id:'cmt',c:'cmt',label:'Conceptual Metaphor Theory',
 def:'The view that metaphor belongs to thought before language: one domain of experience is understood through the structure of another.',
 body:['The theory comes from Lakoff and Johnson [[lakoff1980]]. Your proposal takes from Kövecses the claim that metaphor can structure, restructure and even create reality [[kovecses2017]]. Music theory absorbed the approach through Johnson’s image schemas, as A. Cox records [[coxa2011|paras. 2, 61]].',
 'Two features of your use are unusual. The theory mostly describes conventional metaphors used without awareness, and you apply one on purpose. And it usually explains something abstract through something concrete, while your target, sound design, is already concrete and sensory.'],
 rel:['mapping','kinds','schema','deliberate','mimetic','embodiedfilm','question'],
 q:[['The founding texts are not in the project library. Which edition of Lakoff and Johnson will you cite?','m']]},
{id:'mapping',c:'cmt',label:'Source, target, mapping, entailment',fig:'mapping',
 def:'The source domain lends structure, the target receives it, the mapping is the set of correspondences, and an entailment is what follows in the target because it follows in the source.',
 body:['Your second method is exactly this: mapping a source such as the palimpsest onto the target, sound design [[enoch2026a]]. Mappings are partial, so some parts of a source are conventionally used and others lie idle. The idle parts are where new decisions tend to come from.',
 'A. Cox describes how such a mapping is grounded. A listener finds that a musical experience feels like an experience from another domain, and the metaphor follows from the match [[coxa2011|para. 61]].'],
 rel:['cmt','operable','limit','palimpsest','schema'],
 q:[['For each of the five, which parts of the source domain have you not yet tried to use?','m']]},
{id:'kinds',c:'cmt',label:'Structural and ontological metaphor',
 def:'A structural metaphor organises one domain by another, richly structured one. An ontological metaphor treats something abstract as an entity, substance or container.',
 body:['The distinction is Lakoff and Johnson’s [[lakoff1980]]. It matters here because the project used “ontological metaphor” as its general term for a while, and the research design table still does in the picture-lock row [[enoch2026a]]. Most of the pool is structural. Only the Bubble is ontological in the strict sense.',
 'Your own earlier sense of “ontological” was different and still has work to do: a metaphor as a stance on what sound is, which a designer can inhabit.'],
 rel:['cmt','bubble','palimpsest','flux'],
 q:[['How does an ontological metaphor (sphere, palimpsest) differ from a design metaphor (infection) in how it shapes decisions?','y'],['Are rich structural metaphors more operable than thin ontological ones? The pool lets you test it.','m']]},
{id:'schema',c:'cmt',label:'Image schema',
 def:'A recurring pattern of bodily experience, such as container, path, force or balance, that gives a metaphor its skeleton.',
 body:['The concept is Johnson’s [[johnson1987]]. A. Cox adds the exertion schema, a pattern of effort defined by strength, duration and shape that is shared across ways of making a sound [[coxa2011|para. 45]]. Fahlenbrach applies schemas such as force and balance to sound and picture together [[fahlenbrach2008]].',
 'One reading from your October sessions: the Bubble is a container, the Echo a path that turns back, the Fold a surface bending inward and the Palimpsest a stack of surfaces. A shape used as a picture is illustrative. A shape whose structure drives decisions is operable.'],
 rel:['mimetic','mapping','bubble','echo','fold','palimpsest'],
 q:[['The Infection has no obvious schema in that list. Is it contact, force, or something else?','m']]},
{id:'mimetic',c:'cmt',label:'Mimetic hypothesis',
 def:'We understand sounds partly by covertly imitating the exertions that would produce them. Arnie Cox calls this mimetic motor imagery.',
 body:['The imitation is usually unintended and unnoticed [[coxa2011|paras. 7, 31]]. It runs in three ways: matching the performer’s own actions, substituting another action such as silent singing, and a core bodily effort that follows the music’s energy [[coxa2011|paras. 38–45]]. Music extends a mimetic invitation that listeners take up or refuse, and that is part of liking or disliking it [[coxa2011|paras. 48–51]].',
 'Two points bear on the thesis. Electronic sounds with no visible performer are still grasped mimetically [[coxa2011|para. 54]], which covers most designed sound. And this imagery “motivates and constrains conceptualization” [[coxa2011|para. 61]], a close match for affordances and constraints.'],
 rel:['schema','embodiedfilm','question','bubble','density'],
 q:[['If a metaphor works on the designer’s body first, can the studio log record what the hands did as well as what was intended?','m'],['Does the body end at the skin? Your mentor thinks the Bubble leans on an answer.','f']]},
{id:'embodiedfilm',c:'cmt',label:'Embodied metaphor in film sound',
 def:'Existing research that applies metaphor theory and embodied simulation to film sound.',
 body:['Madupu and Coëgnarts argue that mixers shape loudness, silence, spectrum and space into metaphors that audiences grasp through bodily experience [[madupu2025]]. Madupu analyses his own mixes, so the standpoint is a practitioner’s, but the analysis comes after the work and reads for the audience. Fahlenbrach gives the structural account [[fahlenbrach2008]] and Ward the processual one, in which the body partly re-enacts what it hears [[ward2015]].',
 'Your direction of fit is the reverse. They move from sound to meaning. You move from metaphor to sound design, during the work.'],
 rel:['sonicmetaphor','mimetic','cmt','metsound','spectrum'],
 q:[['Is that reversal the contribution, in one sentence?','m']]},
{id:'deliberate',c:'cmt',label:'Deliberate metaphor',
 def:'A metaphor used on purpose as a metaphor, to change how something is seen or done.',
 body:['Steen’s account covers the gap between the largely unconscious metaphors of the classic theory and your deliberate use of one as a method [[steen2017]]. That shift is both the contribution and the main risk.',
 'Conceptual art gave you an early model. LeWitt describes the idea as a machine that makes the art [[lewitt1967]], and Kosuth locates the work in the idea [[kosuth1969]]. Kim-Cohen carries that lineage into sound [[kimcohen2016|p. 15]].'],
 rel:['cmt','ambience','operable','question'],
 q:[['How do Cox, Kim-Cohen, Kosuth and LeWitt each support or complicate the claim that metaphor does ontological work?','y'],['How do I initiate the sonic metaphor in the visual, theatrical context?','y']]},
/* ---------------- Your practice ---------------- */
{id:'reamp',c:'prac',t:'work',label:'Re-amplification',
 def:'Playing existing recordings through speakers in real spaces and recording the result. Your umbrella term for a practice that runs from sound systems to film mixing.',
 body:['Your essay traces it from a rave in an abandoned building in Prague, through building a sound system, to worldizing as a re-recording mixer. Re-amplifying gave you authorship over material handed over by recordists you never met, and it thickened the recording with choices of speaker, microphone and location [[enoch2026b|Introduction]].',
 'The essay closes by placing the whole constellation of interests under this one word [[enoch2026b|Further Research]].'],
 rel:['worldizing','palimpsest','thick','installation','auralarch'],
 q:[['Can the performance of amplification and re-amplification be thought of as the performance of a palimpsest?','e']]},
{id:'installation',c:'prac',t:'work',label:'“I just need an intimate room…”',
 def:'An intermedia installation in which a subwoofer, mylar, a crochet hoop and two lights turn re-amplified sound into moving light.',
 body:['It absorbed the sound of <i>A corrente das vozes</i> by Sarantopoulos and Vera at the event Resounding Territories. The claim it tests is that sound is a precondition for, and a consequence of, the revelation of meaning in a space [[enoch2026b|Case Study]].',
 'Two accidents became findings. Sound leaked through a sealed door and a book club complained that it was grotesque. And a visitor knocked over by the door turned out to study existentialism and temporality. Connor’s account of sound that will not stay inside walls frames both [[connor2011]].'],
 rel:['reamp','abject','palimpsest','revelation','auralarch'],
 q:[['What could be done to visualise sound inscribing and re-inscribing itself onto places and people?','e']]},
{id:'emchamas',c:'prac',t:'work',label:'Em Chamas: the machine trilogy',
 def:'A sound design built on three appliances (radio, washing machine, refrigerator) and read through Deleuze and Guattari.',
 body:['The two of you designed in turns, like an exquisite corpse, and performed the radio live on several sets before cutting it to picture [[sarantopoulos2026|Our Methodology for Radio Sound Design]]. The Boy is a washing machine, the Mother a refrigerator, the radio the sound of desire.',
 'The paper already states the mechanism the thesis now studies. A character cannot simply be heard as a machine, so the idea had to be applied as a metaphor before it could become literal by the final scene [[sarantopoulos2026|The Boy as a Machine]].'],
 rel:['machines','chion','sonicmetaphor','silence','metsound'],
 q:[['The machine metaphor came from the story. Does a metaphor that originates in the script behave differently from one the designer brings?','m']]},
{id:'atm',c:'prac',t:'work',label:'Anything That Moves',
 def:'A film whose sound you conceived as an infection of a mythic-americana soundscape by a lawn sprinkler and an ice cream truck.',
 body:['It was the first case study and is now, with Stratman’s <i>In Order Not To Be Here</i> [[stratman2002]], a film to think with and not an object of analysis. It remains the source of the Infection and the place where static suburban scenes carry the metaphor.'],
 rel:['infection','horror','thesisfilm'],
 q:[['Can static landscapes initiate impactful audio metaphor for immersive storytelling?','y']]},
{id:'thesisfilm',c:'prac',t:'work',label:'The thesis film',
 def:'A 15 to 20 minute hybrid fiction-documentary speculative horror short on which you are director, writer, sound designer and researcher.',
 body:['Interview-style dialogue is planned for its palimpsestic quality: a spectral present that holds past, present and future at once [[enoch2026a]]. The film is the experiment and the text reports it.',
 'The slide lists the risks plainly: feasibility, four roles that could sway the results, consent for documentary subjects, rights to archival material, and accessibility [[enoch2026a]].'],
 rel:['horror','comparative','text','method','atm'],
 q:[['Too ambitious? Is there enough time, and are there enough resources?','p'],['With four roles, who checks that the writer is not building scenes to suit the metaphor?','m'],['What would a film sound like mixed on your phone?','y']]},
/* ---------------- Ontology of sound ---------------- */
{id:'flux',c:'ont',label:'Sonic flux',fig:'flux',
 def:'Sound as a continuous material flow that human expression contributes to but that precedes and exceeds it.',
 body:['Christoph Cox calls it “an immemorial material flow” [[coxc2018|p. 2]]. He argues for a materialism that refuses the split between subject and object, culture and nature [[coxc2018|pp. 4–5]]. The phonograph is his witness: it does not sort foreground from background, so it shows noise to be the source of articulate sound [[coxc2018|p. 87]].',
 'His ontology uses the same Deleuzian terms as Mader’s history, the virtual and the intensive [[coxc2018|p. 27]]. In your notes the flux is one side of a pair. The other side is the world-for-us of post-production sound, and the infra-thin names what is left between them.'],
 rel:['ambience','intensity','infrathin','soundobject','horror','medium'],
 q:[['If sound exceeds meaning, is a metaphor a way of capturing the flux or of letting more of it through?','m']]},
{id:'ambience',c:'ont',label:'Against ambience',
 def:'Kim-Cohen’s charge that immersive sound and light art retreats from ideas into perception alone.',
 body:['Writing about the New York summer of 2013, he sees forty years of conceptual practice folding back toward art that asks only to be bathed in [[kimcohen2016|pp. 4–5]]. His verdict is blunt: “Ambience is an artistic mode of passivity” [[kimcohen2016|p. 32]]. He credits Christoph Cox as the clearest voice for the realist position he opposes [[kimcohen2016|p. 24]], and Cox answers him by name [[coxc2018|p. 3]].',
 'The stake for the thesis is direct. The Bubble and the Atmosphere are figures of immersion. An operable metaphor is a conceptual move, so the project sits on the line the two authors are arguing over.'],
 rel:['flux','deliberate','bubble','shelf','medium'],
 q:[['Does an operable metaphor make sound design conceptual in Kim-Cohen’s sense, or is it still ambience with a rationale?','m']]},
{id:'intensity',c:'ont',label:'Intensity',fig:'oresme',
 def:'The becoming more or less of a quality (hotter, brighter, more loving), as distinct from an increase in quantity.',
 body:['Mader traces the concept from Aristotle, for whom a change of quality is alteration and never addition [[mader2014|pp. 8–10]], through three medieval theories: a quality is further actualised in its subject, is replaced by a stronger successor, or gains added parts [[mader2014|pp. 14–19]]. The addition theory won, and with it the modern habit of reading intensity straight off an instrument [[mader2014|pp. 5, 19]].',
 'Deleuze resists that reduction. Intensities are registered only through the extended qualities they produce, and philosophy should attend to them before they are coordinated with a scale [[mader2014|pp. 26, 29]]. Your use for this: testing what a mixer means by “needs more intensity” when the answer is not more level.'],
 rel:['flux','machines','density','fold','silence'],
 q:[['A fader is an addition theory of intensity. What would a succession or an actualisation move be at the console?','m']]},
{id:'infrathin',c:'ont',label:'The infra-thin and the trace',fig:'infrathin',
 def:'The barely perceptible interval in which a sound passes from being present to being perceived, leaving a residue of presence.',
 body:['Your essay takes the term from Bonnet, who takes it from Duchamp [[bonnet2016|p. 25]]. It sits beside Kierkegaard’s instant, known only by its traces [[kangas2007|p. 4]], and Chion’s distinction between sound as signal and sound as perceived object [[chion1983|p. 15]]. You argue that the infra-thin is something and not nothing: the first hint of awareness [[enoch2026b|The Instant and the Infrathin]].',
 'With the metaphor’s limit, it is one of the two concepts you chose for the residue between sonic flux and designed sound.'],
 rel:['limit','flux','soundobject','palimpsest','listening'],
 q:[['Where in a mix is the infra-thin audible: in a tail, a pre-echo, a room tone?','m']]},
{id:'limit',c:'ont',label:'The metaphor’s limit',
 def:'The point where a mapping stops producing decisions, or where the sound exceeds what the metaphor can say.',
 body:['Your essay asks how tensile the acoustic palimpsest is and interrogates its limits through Dillon and Daughtry [[enoch2026b|Introduction]]. Constraints are half of the research question [[enoch2026a]], so the limit is a finding and not a failure.',
 'Abels models the gesture on Sloterdijk. After testing his concepts on a real performance she concludes that the sonosphere cannot be an explanatory model and is valuable as a sensitising concept [[abels2016|p. 153]].'],
 rel:['infrathin','mapping','operable','palimpsest','sonosphere','question'],
 q:[['Can a limit be staged in the film, so that the audience hears the metaphor fail?','m']]},
{id:'silence',c:'ont',label:'Silence',
 def:'A designed condition, not an absence: the horizon against which sound is heard.',
 body:['Murch distinguishes silences by what they do, from a cut to a quiet location to the impossible silence that puts us inside a character’s hearing, and he times the slope into each [[murch2005|pp. 27–31]]. His conclusion: “The ultimate metaphoric sound is silence” [[murch2005|p. 32]]. Even a desert had to be given an active silence [[jarrett]].',
 'Jarvis, following Ihde, treats silence as the environment that lets sound be heard at all [[jarvis2024|sec. 2.3]]. In <i>Em Chamas</i> the silence as the Boy burns is the body without organs, a surface of zero intensity [[sarantopoulos2026|The Boy as a Machine;cage1961|p. 173]].'],
 rel:['metsound','horror','machines','intensity','emchamas'],
 q:[['Is silence a sixth metaphor, or the ground all five are drawn on?','m']]},
{id:'soundobject',c:'ont',label:'Signal, sound object, sound event',
 def:'Three ways of saying what a sound is: a measurable signal, an object of perception, or an event with a history.',
 body:['Chion, after Schaeffer, separates the physical signal from the sound object that arises in perception [[chion1983|p. 15]]. Altman prefers the event: a recording is one hearing of something that happened in a space, and theory needs terms that respect that [[altman1992b|p. 16]]. Collins teaches Chion’s three listening modes as the practical entry point [[collins2020|p. 31]].',
 'Jarvis surveys the field and ends on the unresolved question of whether sound should be discussed as an essence and not as a sign or a quality [[jarvis2024|Conclusion]].'],
 rel:['flux','listening','medium','auralarch','infrathin'],
 q:[['Jarvis ends by asking for sound as essence. Do your metaphors answer that, or deliberately decline to?','m']]},
/* ---------------- Listening and knowledge ---------------- */
{id:'listening',c:'lis',label:'Hearing and listening',
 def:'Hearing detects. Listening interprets, and is shaped by culture, technique and attention.',
 body:['Your essay starts from this split [[enoch2026b|Sound, Space, and Aural Architecture;altman1992;blesser2007]]. Jarvis adds Nancy’s pair, understanding versus listening, where listening approaches a meaning that is not yet grasped [[jarvis2024|sec. 2.5]], and Ihde’s variable focus, the listener’s power to reshape the auditory field [[jarvis2024|sec. 2.2]].',
 'Your current reframing rests here: if listening is a form of understanding, then a metaphor that changes how you listen changes what you can do.'],
 rel:['aurality','revelation','soundobject','echo','medium','sonosphere'],
 q:[['How is the spectator forced into an active reading?','y'],['How is the spectator invited to actively experience the soundscape?','y']]},
{id:'aurality',c:'lis',label:'Aurality',
 def:'Listening as a historically located practice that produces knowledge and reaches us through what was written down.',
 body:['Ochoa Gautier reads nineteenth-century Colombian archives in which listening survives as written inscription [[ochoa2014|p. 3]]. She names the mutual shaping of listener, theory of hearing and thing heard an acoustic assemblage [[ochoa2014|p. 22]], and shows that deciding whose voice counted as human was a politics of life [[ochoa2014|p. 9]].',
 'Aurality is a keyword of your palimpsest essay, which wants the acoustic palimpsest to privilege aurality as its own form of experience [[enoch2026b|Abstract]]. Ochoa complicates that wish: historical listening is known only through writing.'],
 rel:['palimpsest','listening','thick','territory'],
 q:[['Whose listening does a metaphor encode? Ochoa’s archive suggests every inscription of sound carries a politics.','m']]},
{id:'medium',c:'lis',label:'Sound as medium',fig:'medium',
 def:'Sound, like light and weather, is something we perceive in. It is not the thing we perceive.',
 body:['Ingold says of weather that it is less what we perceive than “what we perceive in” [[ingold2010|p. S131]], and that the medium is the condition of any interaction, never one of the things interacting [[ingold2010|pp. S132–S133]]. Abels brings in his parallel claim about sound and his rejection of the soundscape concept [[abels2016|p. 139]].',
 'This is the source of the Atmosphere figure. It stands in tension with every account that makes sound an object.'],
 rel:['wayfaring','shelf','soundobject','sonosphere','ambience','fold'],
 q:[['If sound is a medium, what is a sound designer designing?','m']]},
{id:'wayfaring',c:'lis',label:'Wayfaring knowledge',
 def:'Knowledge grown along a path of movement, as opposed to knowledge assembled from fixed points.',
 body:['Ingold contrasts the wayfarer, who knows as he goes, with the passenger carried from A to B [[ingold2010|pp. S126–S127]]. The ground is composite and always forming, and footprints are impressions in it, unlike a stamp pressed from above [[ingold2010|pp. S125, S129]]. The expert differs from the novice in sensitivity to cues, not in stored content [[ingold2010|p. S134]].',
 'For the thesis this supports practice-led research and gives the studio log a model: a trail of decisions. It also contains his objection to the palimpsest.'],
 rel:['method','tagging','palimpsest','medium','revelation'],
 q:[['Is a session file a trail of footprints or a set of stamps?','m']]},
{id:'revelation',c:'lis',label:'Revelation',
 def:'Your current account of what a metaphor does: it adds no sound, it reveals sound, as the world unfolds through a perceiver’s encounters.',
 body:['The word comes from your reading of Ingold and from your own essay, where sound is a precondition for and a consequence of the revelation of meaning in space [[enoch2026b|Introduction]].',
 'Murch describes something close from the mixing desk. The effort of fusing sound and image produces a dimensionality that the mind projects back onto the screen as if it had been there all along [[murch2005|p. 46]].'],
 rel:['sonicmetaphor','listening','wayfaring','installation','metsound'],
 q:[['If the metaphor reveals and does not add, what exactly would an audience notice?','m'],['How do you know the theater is resonating?','y']]},
{id:'thick',c:'lis',label:'Thick description',
 def:'Geertz’s term for reading the stratified layers of meaning in an act. Your word for what re-amplification does to a recording.',
 body:['In the essay, placing a speaker and a microphone in a space maps a hierarchy of meaningful structures onto a recording and so thickens it [[enoch2026b|Introduction;geertz1973|pp. 12–13]]. Rave is called a thick genre for the same reason.',
 'The <i>Em Chamas</i> paper uses the idea again when a broadcast Mass brings its cultural weight into a scene [[sarantopoulos2026|Our Methodology for Radio Sound Design;metz1974|p. 114]].'],
 rel:['reamp','palimpsest','aurality','emchamas'],q:[]},
/* ---------------- Space, sphere, atmosphere ---------------- */
{id:'sphere',c:'spa',label:'Spheres and immune systems',
 def:'Sloterdijk’s claim that humans live in shared interiors of their own making, which protect them as immune systems do.',
 body:['Being in the world means, first, being in spheres [[sloterdijk2011|pp. 45–46]]. Modernity cracked the largest of them, the sky, and left people exposed [[sloterdijk2011|pp. 22–25]]. New spaces are furnished by carrying early spatial experience into them [[sloterdijk2011|p. 12]].',
 'This was your dominant ontology before the turn to metaphor theory, with the palimpsest as the second.'],
 rel:['bubble','sonosphere','infection','horror','auralarch'],
 q:[['Is sound design the building of an envelope that makes a scene inhabitable?','m']]},
{id:'sonosphere',c:'spa',label:'Sonosphere and phonotope',fig:'sonosphere',
 def:'The sphere formed by hearing one another, and within it the sounding interior of one particular community.',
 body:['Abels starts from Sloterdijk’s line that “hearing ourselves is enough” [[abels2016|p. 137]] and sets out the concepts: people are floating beings who tune in to one another, and the phonotope is where hearing one another works as belonging [[abels2016|pp. 141–143]]. Sloterdijk gives a whole chapter to this first sonic alliance [[sloterdijk2011|pp. 477–520]].',
 'Her test case is Palauan chesols chant, which is valid only when the audience answers with a shout [[abels2016|p. 146]]. A schoolgirl’s version broke several conventions and the audience answered anyway, choosing belonging over correctness [[abels2016|pp. 150–152]].'],
 rel:['bubble','sphere','medium','territory','limit','listening'],
 q:[['A cinema audience does not answer back. What is the responsive shout of a film?','m']]},
{id:'auralarch',c:'spa',label:'Aural architecture, spatial signature',
 def:'A space can be heard, and every recording is signed by the space in which it was made.',
 body:['Your essay gathers the functions of listening in space under Blesser and Salter’s aural architecture [[blesser2007]] and tells how the twentieth century cleaned reverberation out of the signal [[thompson2002]]. Altman names what survives: a spatial signature, heard in the cues of each recording [[altman1992a|p. 5]]. Sound is therefore “a Rashomon phenomenon,” existing in the accounts of different hearers [[altman1992b|p. 24]].',
 'Truppin shows the signature used as a design resource. Tarkovsky runs parallel sound, with several worlds present at once and no ranking between real and dreamed [[truppin1992|p. 243]].'],
 rel:['worldizing','reamp','echo','soundobject','rhizome'],
 q:[['Is parallel sound a palimpsest, or a counter-example where layers do not overwrite each other?','m']]},
{id:'territory',c:'spa',label:'Acoustic territories',
 def:'LaBelle’s map of everyday sites, each paired with a sonic figure through which sound makes and unmakes relations.',
 body:['The underground is paired with the echo [[labelle2019|pp. 1–30]] and the street with vibration, a contact below hearing that passes between bodies and surfaces [[labelle2019|pp. 95–97]]. Abels cites the project as the one closest to her own, because it asks how sound relates bodies and not only what sound is [[abels2016|p. 138]].',
 'The structure resembles your pool: a small set of figures, each with its own logic. LaBelle also gives each figure a home.'],
 rel:['echo','infection','sonosphere','aurality'],
 q:[['LaBelle ties each figure to a site. Does each of your metaphors have a home location in the film?','m']]},
{id:'matimag',c:'spa',label:'Material imagination',
 def:'Bachelard’s name for imagination that works from matter (water, air, earth, fire) and not from form.',
 body:['He separates a formal imagination from a material one and sorts poetic temperaments by element [[bachelard1983|pp. 1–3]]. Language itself has a liquid quality for him [[bachelard1983|p. 15]]. The closing chapter, on water’s voice, describes “delegated onomatopoeia”: a sound that has to be produced and projected so that a silent movement can be heard [[bachelard1983|pp. 189–190]].',
 'This is the source behind the Wave. It also reads as a description of Foley. Ingold draws on the same book for his walker leaning into the wind [[ingold2010|p. S131]].'],
 rel:['fold','shelf','medium','mimetic'],
 q:[['Foley is delegated onomatopoeia in practice. Is the Wave closer to your craft than the Fold?','m']]},
{id:'abject',c:'spa',label:'The abject and the grotesque',
 def:'Kristeva’s abject is what does not respect borders and so disturbs identity and order. Your installation earned the word “grotesque” by leaking.',
 body:['In the essay, sound oozes through a taped door and draws attention to the fragility of walls, silence and order [[enoch2026b|Case Study;kristeva1982|p. 14;connor2011]]. The complaint against it set a sounding protest against a quiet afternoon.',
 'The abject links three parts of the thesis: the horror frame, the breach of the Bubble, and the Infection.'],
 rel:['installation','horror','bubble','infection','shelf'],
 q:[['Is the horror of the thesis film abjection (a border failing) or indifference (no border at all)?','m']]},
/* ---------------- Film sound craft ---------------- */
{id:'density',c:'craft',label:'Dense clarity',fig:'twohalf',
 def:'Murch’s aim for a mix in which everything seems to happen at once and each element is still heard.',
 body:['His Law of Two-and-a-half says that with three layers of one kind the mind stops following individuals and hears a group [[murch2005|pp. 16–18]]. Spread across his spectrum, five layers can stay clear, so on <i>Apocalypse Now</i> a layer had to leave whenever another arrived [[murch2005|pp. 19–22]].',
 'He calls the result a subterfuge: the impression of density with the fact of clarity [[murch2005|p. 23]].'],
 rel:['spectrum','comparative','intensity','mimetic','palimpsest'],
 q:[['A palimpsest wants many residual layers and Murch allows five. How do the two rules meet?','m']]},
{id:'spectrum',c:'craft',label:'Encoded and embodied sound',fig:'spectrum',
 def:'Murch’s spectrum from speech, whose meaning sits in a code, to music, whose meaning sits in the sound itself, with effects in between.',
 body:['He asks the reader to think of sound in terms of light and assigns colours from violet dialogue to red music [[murch2005|pp. 8–10]]. The scheme predicts which sounds will blur together and even where they go in the room: cooler sounds in the centre, warmer ones wide [[murch2005|pp. 20–21]].',
 'This is a conceptual metaphor in full working order, and Murch is candid about its status. A theory can move the work forward without being true, as phlogiston once did for chemistry [[murch2005|p. 37]].'],
 rel:['density','operable','embodiedfilm','metsound'],
 q:[['Murch says a theory can help even if it is not true. Is that the right standard for an operable metaphor?','m']]},
{id:'worldizing',c:'craft',label:'Worldizing',
 def:'Playing a sound through a speaker in a real space, re-recording it, and blending the result with the clean original.',
 body:['Murch describes it as acoustic depth of field: the worldized track is thrown out of focus so that a voice can stay sharp in front of it [[murch2005|pp. 33–34]]. He later found the method in Welles’s memo on <i>Touch of Evil</i> [[murch2005|pp. 34–36]]. Collins teaches it as creating the space a sound inhabits [[collins2020|p. 114]].',
 'It is the hinge of your project: the technique you practised before you had a name for the palimpsest [[enoch2026b|Introduction]].'],
 rel:['reamp','palimpsest','auralarch','echo'],
 q:[['What role does Murch’s worldizing play: an example of a palimpsest in practice, or a counter-model?','y']]},
{id:'metsound',c:'craft',label:'Metaphoric sound',
 def:'Murch’s term for sound that does not match what is seen, so that the audience must bridge the gap.',
 body:['The further a sound stands from its image, the more the mind works to connect them and the more dimension the scene gains, up to the point where the thread snaps [[murch2005|pp. 45–47]]. Collins passes the idea on to students [[collins2020|p. 202]]. Bresson says it more severely: image and sound should relay each other [[bresson1977|p. 28]].',
 'This is the craft’s existing sense of metaphor. It works on the audience through a particular sound. Yours works on the designer through a way of deciding.'],
 rel:['silence','operable','sonicmetaphor','chion','revelation','embodiedfilm'],
 q:[['Murch’s metaphoric sound works on the audience and yours on the designer. Do they meet anywhere in the finished film?','m']]},
{id:'rhizome',c:'craft',label:'Rhizomatic sound design',
 def:'Bañuelos Loreto’s proposal to plan the sound of a long take as a rhizome, with many entry and exit points and parallel lines of narrative.',
 body:['He joins Deleuze and Guattari’s rhizome to sound practice [[banuelos2018|pp. 127, 130–132]], treats the script as the first listening [[banuelos2018|p. 133]], and analyses long takes from <i>Son of Saul</i>, <i>True Detective</i> and <i>Damnation</i> [[banuelos2018|pp. 136–144]].',
 'It is the nearest precedent for your move, a philosophical figure offered as a design concept, and it comes from the same university. The author calls it an early-stage proposal [[banuelos2018|p. 145]]. Its analyses describe finished films, which is the gap your decision log is meant to close.'],
 rel:['machines','auralarch','operable','text','chion'],
 q:[['He names a concept and analyses films. What would it take to show the rhizome generating a decision?','m']]},
{id:'chion',c:'craft',label:'Chion’s vocabulary',fig:'tricircle',
 def:'The working terms of audio-vision: the tricircle of sound zones, the acousmêtre, synchresis, anempathetic sound and added value.',
 body:['The <i>Em Chamas</i> paper uses them throughout. The radio crosses the tricircle [[chion2009|p. 255;chion2019|pp. 74–75]] and becomes a phantom acousmêtre [[chion2019|pp. 129–130]]. A lighter synchronised to footsteps relies on synchresis [[chion2019|p. 22]], and cheerful songs intensify pain as anempathetic music [[chion2019|p. 19]].',
 'Your advisor’s notes add the superfield, sorted into conclusive and inconclusive kinds. That term still needs checking against <i>Audio-Vision</i>.'],
 rel:['emchamas','metsound','palimpsest','rhizome'],
 q:[['Is the inconclusive superfield the sonic form of the world-without-us?','m']]},
{id:'machines',c:'craft',label:'Desiring-machines, body without organs',
 def:'Deleuze and Guattari’s account of desire as productive connection, and of a surface of zero intensity on which new connections can be inscribed.',
 body:['In <i>Em Chamas</i> the tuning of a radio is a journey of connections between fragments [[deleuzeguattari2009|pp. 5–6]], breakdown is part of how the machine works [[deleuzeguattari2009|p. 35]], and the silence as the Boy burns is the body without organs [[deleuzeguattari2009|p. 8]].',
 'The vocabulary of degrees and zero intensity connects this paper to Mader’s history, and the body without organs as a surface ready for fresh inscription sits close to a scraped palimpsest [[sarantopoulos2026|The Boy as a Machine]].'],
 rel:['emchamas','intensity','rhizome','silence','palimpsest'],
 q:[['Is the body without organs a blank page or a palimpsest? The answer changes what the film’s final silence means.','m']]}
];

/* ---- 15 Nov 2026 update: intertextuality, extended CMT, embodied brain. q origin n = your reading notes ---- */
(function(){
const N=window.NODES,by=id=>N.find(n=>n.id===id);
window.CLUSTERS.push({id:'brain',label:'The embodied brain',side:'R'},{id:'inter',label:'Intertextuality',side:'L'});
N.push(
/* ---------------- Intertextuality ---------------- */
{id:'intertext',c:'inter',label:'Intertextuality',fig:'intertext',
 def:'Any crossing of texts. In Kristeva’s original sense, a text is already a site where utterances from other texts meet.',
 body:['Klein carries the idea from literary theory into music. Influence is the narrow case that involves an agent borrowing. Intertextuality is the wider, impersonal field in which texts cross whether or not anyone intended it [[klein2005|pp. 2, 11]]. He sorts it by who builds the connection and when: poietic (the maker), esthesic (the listener), historical, transhistorical, and aleatoric [[klein2005|p. 12]]. A later work can therefore change how an earlier one is heard [[klein2005|p. 13]].',
 'This is your new second axis beside metaphor theory. A margin note on Madupu and Coëgnarts states the hunch behind it: films speak to films, we learn from the medium how to hear, and then we absorb that into a physical response.'],
 rel:['code','misreading','imitation','uncanny','aurality','embodiedfilm','palimpsest'],
 q:[['Can abstract, poetic structural metaphors create the conditions for new aesthetic approaches in cinema sound, and how does that connect to films talking to other films?','n'],['A palimpsest is an intertext by construction. Is intertextuality a sixth metaphor, or the theory underneath the first one?','m']]},
{id:'misreading',c:'inter',label:'Bloom’s map of misreading',fig:'bloom',
 def:'Six revisionary ratios by which a later work swerves from, completes, empties, exceeds, curtails or returns to a precursor. Each ratio pairs a trope, a psychic defence and a kind of image.',
 body:['The map is set out as a table [[bloom1975|p. 84]]. The ratios alternate between limitation and representation, and the image pairs read like a list of spatial schemas: presence and absence, part and whole, fullness and emptiness, high and low, inside and outside, early and late. Bloom’s premise is intertextual: to interpret a poem is to interpret its interpretation of other poems [[bloom1975|p. 75]].',
 'You see the ratios as almost exactly your project, pitched differently [[bloom1973]]. Two things follow. Bloom offers a precedent for a small, structured set of named operations. He also ranks metaphor low: it is the trope of askesis, a limitation that locks a poem into images of inside against outside, and strong poems win by overcoming their own metaphors [[bloom1975|pp. 100–101]].',
 'Klein notes that music theorists who borrowed the map mostly kept its structure and dropped its psychology [[klein2005|pp. 17, 30]].'],
 rel:['intertext','imitation','shelf','bubble','echo','palimpsest','limit'],
 q:[['Inside and outside line up with the Bubble, early and late with the Palimpsest and the Echo. Does each of your five map onto one of Bloom’s ratios, and which ratios are left empty?','m'],['Bloom says poems triumph over the limits of their own metaphors. Is that what happens at the metaphor’s limit?','m']]},
{id:'imitation',c:'inter',label:'Heuristic imitation',
 def:'One of Martha Hyde’s four ways a work can answer its past: reverential, eclectic, heuristic and dialectic. Heuristic imitation renews an older language in a current one.',
 body:['Klein uses the type to describe Lutosławski updating Chopin, and summarises all four in a note [[klein2005|pp. 5, 143;hyde1996]]. Dialectic imitation is the strongest: precursor and latecomer meet on equal footing within the work.',
 'For you it is a ready typology of how one film’s sound can answer another’s, and it bears on practitioners working inside a medium. Worldizing already has such a history: Murch found his own technique waiting in Welles’s memo on <i>Touch of Evil</i> [[murch2005|pp. 34–36]].'],
 rel:['intertext','misreading','worldizing','reamp','atm'],
 q:[['Which kind of imitation is the thesis film practising toward Stratman’s <i>In Order Not To Be Here</i>?','m']]},
{id:'code',c:'inter',label:'Code as intertext',
 def:'A convention is a web of earlier uses that listeners have learned. Klein puts it as a definition: “A semiotic code is an intertextuality.”',
 body:['The line comes from his chapter on topics [[klein2005|p. 61]]. Film sound is full of such codes. Madupu and Coëgnarts describe a sudden total silence that works because it breaks what audiences expect, and they ground their sonic metaphors in associations absorbed from life and from cinematic convention alike [[madupu2025|pp. 191–192]]. One of their examples is the mapping of psychological tension onto loudness [[madupu2025|p. 189]].',
 'Kane makes the general argument. To hear one sound as like another, or as like something that is not a sound, is to take part in an auditory culture, and those likenesses are trained [[kane2015|pp. 15–16]]. Your margin note beside their claim of universally felt bodily experience asks whether that can be asserted without evidence.'],
 rel:['intertext','embodiedfilm','ontoaesthetics','aurality','critique','metsound','career'],
 q:[['Is this culturally embodied because of movies speaking to movies?','n'],['A code is a conventional metaphor. If familiarity thins out simulation, are codes the illustrative end of your distinction?','m']]},
{id:'uncanny',c:'inter',label:'Ungrammaticality and the uncanny',
 def:'Riffaterre’s name for a moment where a text stops making sense on its own terms, which signals another text behind it. Klein joins it to Freud’s uncanny and Bloom’s strangeness.',
 body:['For Freud the uncanny is the return of something once familiar, and repetition both summons it and holds it down [[klein2005|p. 79]]. For Riffaterre a text behaves like a neurosis: where it fails to repress its origin in another text, a strangeness appears [[klein2005|pp. 96–97;riffaterre1978]].',
 'This gives the horror frame an intertextual mechanism. A sound that does not belong to its scene can be heard as a breach through which another film, or another layer, shows.'],
 rel:['horror','abject','intertext','palimpsest','metsound','echo'],
 q:[['Is the residue in a palimpsest an ungrammaticality: the place where the erased layer fails to stay erased?','m']]},
/* ---------------- The embodied brain ---------------- */
{id:'ntm',c:'brain',label:'Neural theory of metaphor',
 def:'Lakoff’s account of a conceptual metaphor as a physical circuit linking two regions of the brain, learned when they repeatedly fire together.',
 body:['Two schemas that are regularly active at once become linked, and the link runs from the one that is active more often to the one that is active less. That is why verticality structures quantity and not the reverse. Complex concepts are bound from simpler schemas through gated circuits, and inference works by running the source’s structure on the target [[lakoff2014;lakoffnarayanan2025]]. Imagining and doing use much of the same neural substrate [[galleselakoff2005]].',
 'Two points touch the pool directly. Lakoff works through “bubble” as an example of an image bound to primary metaphors [[lakoff2014]]. And nearly all of this research uses motor, visual or thermal source domains, so audition is barely studied. This summary comes from our October session and from web research, not from texts in the project.'],
 rel:['career','simulation','cmt','schema','bubble','critique'],
 q:[['Hearing never switches off. By Lakoff’s logic, could auditory schemas be strong source domains in their own right?','m']]},
{id:'career',c:'brain',label:'The neural career of a metaphor',fig:'career',
 def:'The finding that sensorimotor regions respond less as a metaphor becomes familiar: novel metaphors are simulated in detail, and conventional ones are processed more abstractly.',
 body:['Desai and colleagues found that activation in motor regions was inversely related to the familiarity of the sentences read [[desai2011]], and a later study found a gradient from literal through metaphoric to idiomatic and abstract language [[desai2013]].',
 'You connect this to the sub-question. A fresh metaphor may do more embodied work for a designer than a worn one, which would make novelty part of what makes a metaphor operable. It is the question you want to put to Coëgnarts: can a new, poetic metaphor open approaches that a familiar one cannot?',
 'A caution on scope. The experiments measure people reading sentences about actions. Applying them to a designer working inside a metaphor for months is an inference of yours, to be tested in the studio log.'],
 rel:['operable','ntm','deliberate','code','critique','tagging'],
 q:[['If familiarity dulls simulation, does a metaphor stop being operable once you are used to it, and can the studio log show that happening?','m']]},
{id:'simulation',c:'brain',label:'Embodied simulation',
 def:'The mechanism by which we grasp another’s actions, sensations and feelings by partly re-enacting them. Its form in art is called liberated simulation, experienced as a Feeling of Body.',
 body:['Ward builds his account of cinematic sound on Gallese’s theory. Feeling of Body comes before, and underlies, any reading of a character’s mind [[ward2017|p. 138;wojciehowski2011]]. His central claim is that cinematic sound means chiefly by what it makes an audience’s body feel, and by how it shapes that feeling [[ward2017|p. 238]]. Audition sits at the centre because audiovisual mirror neurons respond to an action whether it is done, seen or only heard [[ward2017|p. 135;kohler2002]]. He cites Foley as the craft example [[ward2017|p. 280]].',
 'A. Cox draws on the same evidence and is more guarded: such neurons had not been directly observed in humans, so they remain suggestive [[coxa2011|para. 13]].',
 'Ward’s thesis is the closest model for yours, a sound designer theorising practice through embodied cognition. The difference is direction. He explains reception. You ask what a metaphor does for the designer while designing.'],
 rel:['mimetic','embodiedfilm','ntm','crossmodal','critique','matimag','bubble'],
 q:[['Ward starts from professional intuitions and grounds them in science. Is your starting point the same, with metaphor in place of intuition?','m']]},
{id:'crossmodal',c:'brain',label:'Sense modalities, crossmodal correspondence',
 def:'The senses are not separate channels. What is heard shapes what is seen, tasted and touched, and the reverse.',
 body:['Collins gathers the evidence for sound designers: asked to give lemons a sound, most people choose a high one and feel it in the face; rounded and spiky shapes pair with different speech sounds, by touch as well as sight; a sound alone can report an object’s size and material [[collins2020|pp. 186–187]]. Ward lists correspondences of loudness with height, pitch with size and distance, and transients with roughness [[ward2017|p. 95]]. Madupu and Coëgnarts use a model in which audiences build a working narrative from several channels at once [[madupu2025|p. 179]].',
 'This is your sense-modalities interest: that other senses carry sound information and complete a totality of perception. You link it to Thom’s seven events. Chattopadhyay asserts something similar, and your note asks whether it is true [[chatt2017|p. 12]]. Goodman pushes furthest, placing vibration before the division into senses, and Kane disputes him [[kane2015|p. 5]].'],
 rel:['simulation','thom','mimetic','spectrum','critique','matimag','schema'],
 q:[['The sense modalities provide audio information: very cool, but is this true?','n'],['Ward cautions that many of these findings were made with music and may not extend to everyday sound. Which hold for designed sound against picture?','m']]},
{id:'critique',c:'brain',label:'Limits of the embodiment claim',
 def:'Three objections to grounding meaning in the body: the neural evidence is thinner than the confidence placed in it, affect is not prior to thought, and the body that responds has been trained by a culture.',
 body:['Casasanto and Gijssels argue that much of the evidence shows an association between domains in the mind and not a simulation of the source in the motor system. They propose the term mental metaphor [[casasanto2015]].',
 'Kane answers the claim that sound acts on the body before cognition. A feared sound that turns out to be harmless changes its affect with no change in vibration, so knowledge reaches affect [[kane2015|pp. 6–7]]. Splitting the two repeats the dualism it claims to escape, a point he takes from Leys [[kane2015|pp. 7–8;leys2011]]. Against it he sets Sterne’s audile technique, built on Mauss: the body is a first technical object, trained by education and society, so bodies are cultivated as cultures are embodied [[kane2015|p. 8]].',
 'This protects the thesis. A metaphor deliberately practised until it lives in the hands is an audile technique in the making.'],
 rel:['ontoaesthetics','code','career','simulation','ntm','aurality','mimetic'],
 q:[['They say such contrasts tie into bodily experience that everyone shares. Do they? Can you really claim this without evidence?','n'],['If the body is trained, is learning to work inside a metaphor a form of training that the studio log can document?','m']]}
);
/* ---------------- additions to existing clusters ---------------- */
N.push(
{id:'thom',c:'met',t:'met',label:'Thom’s seven events',
 def:'René Thom’s seven elementary catastrophes, the basic ways a form can change, as cited by Deleuze: the fold, the crease, the dovetail, the butterfly, and the hyperbolic, elliptical and parabolic umbilics.',
 body:['Deleuze introduces them as transformations that project inner, hidden variables onto outer space, a morphology of living matter [[deleuze2006|p. 16]]. The fold is the first and simplest of the seven.',
 'You were excited to find them and connect them to the sense modalities. They are not yet a candidate metaphor. They are a possible vocabulary of transformations, which is closer to what a designer does to a sound than any single image is.'],
 rel:['fold','crossmodal','schema','shelf','operable'],
 q:[['Seven named transformations is a ready-made set of operations. Could each be defined as a move on a sound, and would that be operable or only a relabelling?','m']]},
{id:'extended',c:'cmt',label:'Extended CMT',
 def:'Kövecses’s revision of the theory, in which a metaphor exists at several levels of schematicity at once and is shaped by the context it is used in.',
 body:['In outline, the levels run from image schemas through domains and frames to the mental spaces built during a particular act of thinking, and context includes the situation, the surrounding discourse, what the thinker already knows, and the body [[kovecses2020]]. This summary is from general knowledge of the book, which is on your reading list and not in the project, so it carries no page numbers.',
 'It matters for two reasons. The lowest, most specific level is where a designer in a session actually works, which is where an operable metaphor would have to live. And the stress on context gives the theory a way to hold convention and intertext, which the classic version leaves out.'],
 rel:['cmt','schema','deliberate','mapping','code','operable'],
 q:[['At which level does each of the five sit: an image schema, a domain, a frame, or something built fresh in the session?','m']]},
{id:'ontoaesthetics',c:'ont',label:'Onto-aesthetics and its critic',
 def:'The belief that an artwork can disclose its own ontology. Kane names it in order to reject it.',
 body:['Kane’s targets here are Christoph Cox and Greg Hainge. His objection is a category mistake: a work embodies its ontology completely, as everything does, but only exemplifies selected properties, and exemplifying is an act of reference that depends on a shared system of signs [[kane2015|pp. 11–13]]. So when Cox hears room tone as disclosing sound’s nature, he is drawing an analogy between a shift of attention and a metaphysical shift, and an analogy holds only inside a culture that shares it [[kane2015|pp. 13–16]]. Kane renames the project ontography: describing what a community takes to exist [[kane2015|p. 16]].',
 'Your notes have used onto-aesthetics for your own focus. The critique is also the best argument for the turn you have made, since conceptual metaphor and intertextuality are theories of analogy and of shared likeness. Chattopadhyay reaches a similar place from inside sound art, moving attention from the object to the listener [[chatt2017|p. 4]].'],
 rel:['flux','ambience','code','critique','situation','aurality','kinds'],
 q:[['Kane says ontological claims about sound work only by analogy. Is that a criticism of your metaphors or a description of them?','m'],['Do you keep the word onto-aesthetics, and if so, in whose sense?','m']]},
{id:'situation',c:'lis',label:'Auditory situation, sonic subject',
 def:'Chattopadhyay’s alternatives to the sound object: the situation that unfolds around a listener as sounds occur, and the listener in whom their meaning forms.',
 body:['He argues that sound art inherited the object from the visual arts and should attend instead to the how of listening [[chatt2017|pp. 2, 6]]. Meaning forms in memory, imagination and contemplation, which he calls the sonic subject, and curating moves into the listener’s head [[chatt2017|pp. 7, 9]]. He draws on Indian aesthetics for a distinction between sound heard by the ear and sound grasped by the mind [[chatt2014|p. 2]].',
 'Hyper-listening is his name for the practice: attending to the moods and thoughts a sound sets off once it is cut loose from its source, and refusing to equate listening with understanding [[chatt2014|pp. 7–8]]. Your notes mark one passage as answering whether a metaphor can be embodied, and another as a ready exercise for teaching: room tone sent to architects who draw the room they hear [[chatt2017|pp. 7, 10]].'],
 rel:['imagination','listening','soundobject','ontoaesthetics','revelation','medium','ambience'],
 q:[['Are metaphors rootless networks of psychic personalization?','n'],['He says the nomadic listener navigates psychogeographically. OK, but how?','n'],['Chattopadhyay asks whether sound is public before it is private. You marked it a great question. What is your answer for a film mix?','n']]},
{id:'imagination',c:'lis',label:'Auditory imagination',
 def:'Ihde’s account of imagined sound as a mode of experience that runs alongside perceived sound, in what he calls a polyphony of experience.',
 body:['Imagined sound can re-present what was heard or exceed it, and it is co-present with perception [[ihde1976|pp. 121–127]]. Listening also reaches where sight cannot: “I hear interiors” [[ihde1976|p. 70]]. A struck object reports what it is made of. And the auditory field has a horizon, and that horizon is silence [[ihde1976|pp. 111–112]].',
 'For the thesis this describes the designer’s first act, hearing a metaphor before building it. A. Cox would add that imagining an action runs on the same motor areas as doing it [[coxa2011|para. 20]]. One of your notes pushes back on a claim Chattopadhyay takes from Altman, that sound becomes actual only at the ear: a sound heard in the head seems actual already [[chatt2014|p. 6]].'],
 rel:['situation','silence','mimetic','bubble','listening','revelation','simulation'],
 q:[['If a sound imagined is already actual, where does the design begin: in the head or at the fader?','n']]}
);
/* ---------------- edits to existing nodes ---------------- */
let n=by('fold');
n.body[0]='You asked for this one to be Deleuzian or Ingoldian. Deleuze treats the fold as an operation and not an image: the Baroque “endlessly produces folds” of matter below and of the soul above [[deleuze2006|p. 3]], and in Mallarmé it is less a notion than the operation that makes the poetry [[deleuze2006|p. 34]]. Perception is unfolding. Clear perception is drawn out of a dust of minute perceptions too small to notice singly, as the roar of the sea is made of waves no one hears [[deleuze2006|pp. 99–106]]. Texture is how a material is folded [[deleuze2006|p. 41]]. The Ingoldian half, a being as an enfoldment of life’s generative potential, is still to be sourced [[ingold2000|p. 19]].';
n.q[1]=['Minute perceptions read like a theory of room tone and sub-audible layers. Is that the Fold’s first operable instruction?','m'];
n.rel.push('thom','imagination');
n=by('bubble');
n.body.push('Three newer sources thicken it. Ihde describes hearing the inside of things, which gives containment a basis in listening [[ihde1976|p. 70]]. Ward analyses a film’s spaces as acoustic containers, each built to induce a feeling-state, and calls the result emoacoustics [[ward2017|p. 234]]. Lakoff uses “bubble” as his worked example of an image bound to primary metaphors [[lakoff2014]]. Bloom is the warning: metaphor traps a poem in inside against outside [[bloom1975|pp. 100–101]].');
n.rel.push('imagination','ntm','misreading');
n=by('operable');
n.body.push('The neuroscience you are reading suggests a third property. Unfamiliar metaphors recruit more sensorimotor simulation than familiar ones [[desai2011]], so an operable metaphor may need to be a fresh one.');
n.rel.push('career','extended');
n=by('sonicmetaphor');
n.body[1]=n.body[1].replace('[[madupu2025]]','[[madupu2025|p. 192]]');
n=by('embodiedfilm');
n.body=['Madupu and Coëgnarts argue that mixers shape four kinds of dynamics (range, loudness and silence, spectrum, and sound field) into metaphors that audiences grasp through bodily experience [[madupu2025|pp. 180–181]]. They use container logic for the nested spaces of a soundtrack [[madupu2025|p. 182]]. Madupu analyses his own mixes, so the standpoint is a practitioner’s, but the analysis comes after the work and reads for the audience.',
 'Ward’s doctoral thesis is the fullest practitioner account. Audiovisual metaphor maps qualities of a sound onto an image so that a thing acquires weight and force, and crafting it is a form of emotion design [[ward2017|pp. 109, 183]]. He builds on Fahlenbrach, who supplies the structural account in terms of image schemas [[fahlenbrach2008]].',
 'Your direction of fit is the reverse. They move from sound to meaning. You move from metaphor to sound design, during the work. You have written to Coëgnarts and are reading the volume he co-edited.'];
n.rel.push('simulation','code','crossmodal');
n=by('cmt');
n.body.push('You made your own list of ontological metaphors before learning that this was an established field, and are now working backwards to fit it into the literature. The current aim is to combine metaphor theory with intertextuality in order to find operable metaphors, beginning from the idea of mapping them onto working techniques inside the DAW.');
n.rel.push('extended','ntm','intertext');
n.q=[['What does a mapping onto DAW techniques look like for one metaphor, written out as a table of entailments?','m']];
n=by('flux');
n.body.push('Kane’s critique lands here. To say that a work discloses the flux is, he argues, to slip a culturally learned analogy into a supposedly culture-free ontology [[kane2015|pp. 13–15]].');
n.rel.push('ontoaesthetics');
by('ambience').rel.push('ontoaesthetics');
n=by('silence');
n.body[1]='Ihde treats silence as the horizon of the auditory field, given only as absence and never the simple opposite of sound [[ihde1976|pp. 111–112]]. Jarvis follows him [[jarvis2024|sec. 2.3]]. Madupu and Coëgnarts add that a total silence works by breaking a learned convention [[madupu2025|p. 191]]. In <i>Em Chamas</i> the silence as the Boy burns is the body without organs, a surface of zero intensity [[sarantopoulos2026|The Boy as a Machine;cage1961|p. 173]].';
n.rel.push('imagination','code');
by('horror').rel.push('uncanny');
n=by('shelf');
n.body[1]='A cohort pedagogy with one designer per metaphor, and a film designed five times and spliced, are parked as future extensions [[enoch2026a]]. Bloom’s revisionary ratios, which you see as close kin to the pool, now have their own entry [[bloom1973]].';
n.rel.push('misreading','thom');
by('palimpsest').rel.push('intertext','uncanny');
by('mimetic').rel.push('simulation','critique');
by('listening').rel.push('situation','imagination');
by('aurality').rel.push('code','critique');
const c=window.CENTER;
c.body[0]+=' Since November the reading has widened in three directions: intertextuality, an extended metaphor theory, and the neuroscience of sensorimotor embodiment.';
c.body[1]='The right-hand side of the map holds the thesis itself: its frame, the metaphors, the theory of metaphor, the embodied brain and your own work. The left-hand side holds what the wider reading supplies: what sound is, how listening knows, how sound makes space, how mixers already think, and how works answer other works.';
c.rel=['question','operable','palimpsest','cmt','intertext','career','flux','density'];
})();
